// Una fila por reel, solo lo útil. «lectura» = SOLO los que destacan (Abel 09/10/2026: «este sí, este sí»); el resto en blanco.
const ahora = Date.now();
const F = $input.all().map(it => {
  const m = it.json, ins = {};
  for (const x of (m.insights?.data || m.data || [])) ins[x.name] = x.values?.[0]?.value ?? x.total_value?.value ?? '';
  return { fecha: m.timestamp.slice(0, 10), titulo: (m.caption || '').split('\n')[0].slice(0, 120),
    vistas: ins.views, me_gusta: ins.likes, comentarios: ins.comments, compartidos: ins.shares, guardados: ins.saved,
    interacciones: ins.total_interactions, segundos_vista: ins.ig_reels_avg_watch_time ? Math.round(ins.ig_reels_avg_watch_time / 100) / 10 : '',
    lectura: '', enlace: m.permalink, id: 'ig_' + m.id,   // id como texto: Sheets estropea los números largos
    _edad: (ahora - new Date(m.timestamp.replace('+0000', 'Z')).getTime()) / 864e5 };
});
const ok = F.filter(f => f._edad >= 3 && f.vistas > 0);                     // solo reels con 3 días o más
const pg = f => f.guardados / f.vistas, pc = f => f.compartidos / f.vistas;
const nota = (f, t) => { f.lectura = f.lectura ? f.lectura + ' · ' + t : t; };
if (ok.length) {
  const mv = ok.reduce((a, f) => a + f.vistas, 0) / ok.length;
  const puntos = f => f.vistas / mv + pg(f) * 25 + pc(f) * 40;                  // vistas relativas + guardar + compartir
  const mejor = [...ok].sort((a, b) => puntos(b) - puntos(a))[0];
  nota(mejor, `🏆 EL MEJOR: ${mejor.vistas} vistas, ${mejor.guardados} guardados, ${mejor.compartidos} compartidos`);
  [...ok].sort((a, b) => b.vistas - a.vistas).slice(0, 3).forEach(f => nota(f, `👁 TOP VISTAS (${f.vistas})`));
  const fiables = ok.filter(f => f.vistas >= 1000);
  if (fiables.length) { const g = [...fiables].sort((a, b) => pg(b) - pg(a))[0]; nota(g, `💾 EL QUE MÁS SE GUARDA (${(pg(g) * 100).toFixed(1)} %)`); }
  ok.filter(f => !f.lectura && f.vistas >= 1000 && (pg(f) >= 0.04 || f.compartidos >= 20))
    .forEach(f => nota(f, `✅ SÍ: guarda ${(pg(f) * 100).toFixed(1)} %, ${f.compartidos} compartidos`));
}
return F.map(({ _edad, ...f }) => ({ json: f }));
